// PF Mock Booking: edit the list below, then run the workflow.
// Each entry makes one fake Calendly booking and sends it through PF Calendly Capture.
//   p:        participant number -> email aniol.moner+p<N>@n8n.io, name "<first name> Mock"
//   startIn:  minutes from now until the session starts
//   duration: session length in minutes
//   kind:     'research' | 'continuous_discovery' | 'uxr_recruiting'
const bookings = [
  { p: 5, startIn: -2, duration: 4, kind: 'continuous_discovery' },
];

const RR = 'https://api.calendly.com/event_types/ebd64db8-7c09-4e31-bc2e-339065fbb930';
const RESEARCH_ET = 'https://api.calendly.com/event_types/MOCK-ET-RESEARCH';
const runId = $now.toFormat('yyyyLLdd-HHmmss');
const names = ['Alex', 'Bea', 'Cris', 'Dani', 'Eli', 'Fran', 'Gal', 'Hugo', 'Iris', 'Jon'];

return bookings.map((b) => {
  const code = `${runId}-P${b.p}`;
  const start = $now.plus({ minutes: b.startIn }).startOf('second');
  const end = start.plus({ minutes: b.duration });
  const first = names[(b.p - 1) % names.length];
  const tracking = b.kind === 'uxr_recruiting'
    ? { utm_source: 'uxr_recruiting', utm_medium: 'email', utm_campaign: `batch_mock-${runId}` }
    : {};
  return {
    json: {
      event: 'invitee.created',
      payload: {
        uri: `https://api.calendly.com/scheduled_events/MOCK-EVT-${code}/invitees/MOCK-INV-${code}`,
        email: `aniol.moner+p${b.p}@n8n.io`,
        name: `${first} Mock`, first_name: first, last_name: 'Mock',
        status: 'active', timezone: 'Europe/Madrid',
        rescheduled: false, old_invitee: null, new_invitee: null,
        reschedule_url: `https://calendly.com/reschedulings/MOCK-${code}`,
        cancel_url: `https://calendly.com/cancellations/MOCK-${code}`,
        cancellation: null, no_show: null, tracking,
        scheduled_event: {
          uri: `https://api.calendly.com/scheduled_events/MOCK-EVT-${code}`,
          name: b.kind === 'research' ? 'Mock research session' : 'Research with n8n',
          event_type: b.kind === 'research' ? RESEARCH_ET : RR,
          start_time: start.toUTC().toISO(), end_time: end.toUTC().toISO(), status: 'active',
          event_memberships: [{ user: 'https://api.calendly.com/users/MOCK-HOST', user_email: 'aniol.moner@n8n.io', user_name: 'Aniol Moner' }],
        },
      },
    },
  };
});
